// PlansServiceHandler is an implementation of the vrooli.plan_manager.v1.plans.PlansService
// service.
type PlansServiceHandler interface {
	// ListPlans returns plans, optionally filtered by status (OT-P0-001).
	ListPlans(context.Context, *connect.Request[plans.ListPlansRequest]) (*connect.Response[plans.ListPlansResponse], error)
	// GetPlan returns one plan by id or slug.
	GetPlan(context.Context, *connect.Request[plans.GetPlanRequest]) (*connect.Response[plans.GetPlanResponse], error)
	// CreatePlan persists a new structured plan; the server assigns id, content
	// hash, status and timestamps (the computed fields).
	CreatePlan(context.Context, *connect.Request[plans.CreatePlanRequest]) (*connect.Response[plans.CreatePlanResponse], error)
	// UpdatePlan replaces the authored fields of an existing plan; computed fields
	// are recomputed server-side.
	UpdatePlan(context.Context, *connect.Request[plans.UpdatePlanRequest]) (*connect.Response[plans.UpdatePlanResponse], error)
	// ArchivePlan soft-archives a plan (kept, hidden by default).
	ArchivePlan(context.Context, *connect.Request[plans.ArchivePlanRequest]) (*connect.Response[plans.ArchivePlanResponse], error)
	// RenderMarkdown renders the structured record to its human-readable markdown
	// projection. Deterministic; the view is never parsed back into truth.
	RenderMarkdown(context.Context, *connect.Request[plans.RenderMarkdownRequest]) (*connect.Response[plans.RenderMarkdownResponse], error)
	// AddPhase appends a first-class phase to a plan.
	AddPhase(context.Context, *connect.Request[plans.AddPhaseRequest]) (*connect.Response[plans.AddPhaseResponse], error)
	// UpdatePhase replaces the authored fields of a phase. Status is a typed
	// transition — see ExecutionService.TransitionPhase for runtime transitions.
	UpdatePhase(context.Context, *connect.Request[plans.UpdatePhaseRequest]) (*connect.Response[plans.UpdatePhaseResponse], error)
	// ListRelevantContext returns accepted setup context for a plan or one phase.
	ListRelevantContext(context.Context, *connect.Request[plans.ListRelevantContextRequest]) (*connect.Response[plans.ListRelevantContextResponse], error)
	// UpdateRelevantContext replaces one structured setup item without rewriting
	// the whole plan.
	UpdateRelevantContext(context.Context, *connect.Request[plans.UpdateRelevantContextRequest]) (*connect.Response[plans.UpdateRelevantContextResponse], error)
	// RemoveRelevantContext removes one structured setup item.
	RemoveRelevantContext(context.Context, *connect.Request[plans.RemoveRelevantContextRequest]) (*connect.Response[plans.RemoveRelevantContextResponse], error)
	// ListReferences returns structured code/doc/req references for a plan or one
	// phase.
	ListReferences(context.Context, *connect.Request[plans.ListReferencesRequest]) (*connect.Response[plans.ListReferencesResponse], error)
	// UpdateReference replaces one structured reference without rewriting the
	// whole plan.
	UpdateReference(context.Context, *connect.Request[plans.UpdateReferenceRequest]) (*connect.Response[plans.UpdateReferenceResponse], error)
	// RemoveReference removes one structured reference.
	RemoveReference(context.Context, *connect.Request[plans.RemoveReferenceRequest]) (*connect.Response[plans.RemoveReferenceResponse], error)
	// GetGraph returns the supersession/dependency edges, optionally scoped to one
	// plan's neighborhood (OT-P1-002).
	GetGraph(context.Context, *connect.Request[plans.GetGraphRequest]) (*connect.Response[plans.GetGraphResponse], error)
	// LinkSupersession records that one plan supersedes another (PM-GRAPH-001).
	LinkSupersession(context.Context, *connect.Request[plans.LinkSupersessionRequest]) (*connect.Response[plans.LinkSupersessionResponse], error)
	// LinkDependency records that one plan depends on another.
	LinkDependency(context.Context, *connect.Request[plans.LinkDependencyRequest]) (*connect.Response[plans.LinkDependencyResponse], error)
	// ImportPlan canonicalizes a markdown plan from a configured source location into the
	// structured model (references parsed from the [CODE:]/[REQ:] grammar).
	ImportPlan(context.Context, *connect.Request[plans.ImportPlanRequest]) (*connect.Response[plans.ImportPlanResponse], error)
	// MigratePlan canonicalizes a fallback-resolved plan into the home store
	// (non-destructive to the source).
	MigratePlan(context.Context, *connect.Request[plans.MigratePlanRequest]) (*connect.Response[plans.MigratePlanResponse], error)
	// ReconcilePlans repairs rendered mirrors and canonicalizes misplaced markdown
	// sources non-destructively.
	ReconcilePlans(context.Context, *connect.Request[plans.ReconcilePlansRequest]) (*connect.Response[plans.ReconcilePlansResponse], error)
	// ListTemplates returns the per-surface plan templates (CLI/proto/UI).
	ListTemplates(context.Context, *connect.Request[plans.ListTemplatesRequest]) (*connect.Response[plans.ListTemplatesResponse], error)
	// CreateFromTemplate pre-scaffolds a plan from a template.
	CreateFromTemplate(context.Context, *connect.Request[plans.CreateFromTemplateRequest]) (*connect.Response[plans.CreateFromTemplateResponse], error)
	// ListAuditFacts exposes Plan Manager's authoritative, run-scoped mutation
	// facts for evidence reconciliation. It is read-only and does not transfer
	// ownership of plans or Agent Manager identity to another scenario.
	ListAuditFacts(context.Context, *connect.Request[plans.ListAuditFactsRequest]) (*connect.Response[plans.ListAuditFactsResponse], error)
}

